def solve(script):
    stack = []
    tokens = script.split()
    for token in tokens:
        if token == 'OP_ADD':
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif token == 'OP_DUP':
            stack.append(stack[-1])
        elif token == 'OP_EQUAL':
            b = stack.pop()
            a = stack.pop()
            stack.append(1 if a == b else 0)
        else:
            stack.append(int(token))
    return str(stack[-1])
